import boto3

def get_text(block, blocks_dict):
    text = ''
    if 'Relationships' in block:
        for relationship in block['Relationships']:
            if relationship['Type'] == 'CHILD':
                for child_id in relationship['Ids']:
                    child = blocks_dict.get(child_id)
                    if child and child['BlockType'] == 'WORD':
                        text += child['Text'] + ' '
    return text.strip()

def get_kv_map(blocks):
    blocks_dict = {b['Id']: b for b in blocks}
    key_map = {}
    value_map = {}
    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'KEY' in block['EntityTypes']:
                key_map[block['Id']] = block
            elif 'VALUE' in block['EntityTypes']:
                value_map[block['Id']] = block
    kv_pairs = {}
    for k_id, k_block in key_map.items():
        value_id = None
        if 'Relationships' in k_block:
            for rel in k_block['Relationships']:
                if rel['Type'] == 'VALUE':
                    if rel['Ids']:
                        value_id = rel['Ids'][0]
                    break
        if value_id and value_id in value_map:
            v_block = value_map[value_id]
            key_text = get_text(k_block, blocks_dict)
            value_text = get_text(v_block, blocks_dict)
            confidence = min(k_block['Confidence'], v_block['Confidence'])
            kv_pairs[key_text.lower()] = {
                'value': value_text,
                'confidence': confidence
            }
    return kv_pairs

def validate_structured_fields(document_bytes: bytes, required_fields: list[str], min_confidence: float = 0.95) -> dict:
    client = boto3.client('textract')
    response = client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['FORMS']
    )
    kv_pairs = get_kv_map(response['Blocks'])
    validation = {}
    for field in required_fields:
        field_lower = field.lower().strip()
        match = None
        for key_lower, data in kv_pairs.items():
            if field_lower in key_lower or key_lower in field_lower:
                match = data
                break
        if match:
            conf = match['confidence']
            is_valid = conf >= min_confidence
            validation[field] = {
                'found': True,
                'value': match['value'],
                'confidence': conf,
                'valid': is_valid
            }
        else:
            validation[field] = {
                'found': False,
                'value': None,
                'confidence': 0.0,
                'valid': False
            }
    all_valid = all(item['valid'] for item in validation.values())
    return {
        'all_valid': all_valid,
        'details': validation
    }
